package dev.differentenchant;
import dev.differentenchant.lost.*;
import dev.differentenchant.research.*;
import dev.differentenchant.client.WaterReflectionClient;
import java.nio.file.*;
import java.util.*;
import net.fabricmc.fabric.api.client.gametest.v1.FabricClientGameTest;
import net.fabricmc.fabric.api.client.gametest.v1.context.*;
import net.fabricmc.fabric.api.client.gametest.v1.world.TestWorldSave;
import net.minecraft.core.*;
import net.minecraft.core.registries.Registries;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.projectile.arrow.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.phys.*;
import net.minecraft.server.level.*;
public final class BatchTwoClientGameTest implements FabricClientGameTest {
    private static void check(boolean b,String s){if(!b)throw new AssertionError(s);}
    private static ItemStack gear(ServerLevel level,Item item,String id,int rank){var stack=new ItemStack(item);stack.enchant(level.registryAccess().lookupOrThrow(Registries.ENCHANTMENT).get(ResearchContent.id(id)).orElseThrow(),rank);return stack;}
    private static void vanilla(ServerLevel level,ItemStack stack,String id,int rank){stack.enchant(level.registryAccess().lookupOrThrow(Registries.ENCHANTMENT).get(net.minecraft.resources.Identifier.withDefaultNamespace(id)).orElseThrow(),rank);}
    private static void shot(ClientGameTestContext c,String name){c.runOnClient(client->{client.getToastManager().clear();client.gui.getChat().clearMessages(true);});c.waitTick();c.takeScreenshot("lost2-"+name);}
    private static void aim(ClientGameTestContext c,double x,double y,double z){var a=c.computeOnClient(client->{var eye=client.player.getEyePosition();double dx=x-eye.x,dy=y-eye.y,dz=z-eye.z;return new float[]{(float)(Math.toDegrees(Math.atan2(dz,dx))-90),(float)-Math.toDegrees(Math.atan2(dy,Math.sqrt(dx*dx+dz*dz)))};});c.getInput().lookAt(a[0],a[1]);c.waitTick();}
    private static void base(TestSingleplayerContext w,double x,double y,double z){w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();p.stopUsingItem();p.clearFire();p.setGameMode(GameType.SURVIVAL);p.setHealth(20);p.getFoodData().setFoodLevel(20);p.getInventory().clearContent();p.setItemSlot(EquipmentSlot.FEET,ItemStack.EMPTY);p.setItemSlot(EquipmentSlot.HEAD,ItemStack.EMPTY);p.setItemSlot(EquipmentSlot.CHEST,ItemStack.EMPTY);p.teleportTo(x,y,z);});}
    private static void language(ClientGameTestContext c,String code){var f=c.computeOnClient(client->{client.getLanguageManager().setSelected(code);client.options.languageCode=code;return client.reloadResourcePacks();});c.waitFor(client->f.isDone()&&client.getOverlay()==null);c.waitTicks(2);}
    private static void tooltips(ClientGameTestContext c,TestSingleplayerContext w,String code){
        language(c,code);w.getServer().runOnServer(server->{var p=server.getPlayerList().getPlayers().getFirst();int i=9;for(var id:List.of("hush_step","borrowed_flame","returning_feather","swift_draw","paper_kite","parry","undertow","water_reflection","star_bridge")){var h=server.registryAccess().lookupOrThrow(Registries.ENCHANTMENT).get(ResearchContent.id(id)).orElseThrow();var book=ResearchBooks.output(server.registryAccess(),new ResearchPolicy.Result(h.key().identifier().toString(),h.value().getMaxLevel(),1,false));p.getInventory().setItem(i++,book);}});c.waitTicks(3);
        c.runOnClient(client->{for(int i=9;i<18;i++){var lines=net.minecraft.client.gui.screens.Screen.getTooltipFromItem(client,client.player.getInventory().getItem(i));String text=lines.stream().map(net.minecraft.network.chat.Component::getString).collect(java.util.stream.Collectors.joining(" "));check(lines.size()>=3&&!text.contains("enchantment.differentenchant")&&!text.contains("Rarity")&&!text.contains("Research grade")&&!text.contains("稀有度")&&!text.contains("研究评级"),"localized real item tooltip has effect but no internal tier: "+code+" "+text);}});
        c.getInput().pressKey(o->o.keyInventory);c.waitForScreen(net.minecraft.client.gui.screens.inventory.InventoryScreen.class);var xy=c.computeOnClient(client->{double scale=client.getWindow().getGuiScale();return new double[]{((client.screen.width-176)/2+34)*scale,((client.screen.height-166)/2+92)*scale};});c.getInput().setCursorPos(xy[0],xy[1]);c.waitTicks(2);shot(c,"13b-new-books-tooltip-"+code);c.getInput().pressKey(o->o.keyInventory);c.waitForScreen(null);
    }
    @Override public void runTest(ClientGameTestContext c){
        c.getInput().resizeWindow(1280,720);TestWorldSave save;String dataJson;var report=new StringBuilder();var trajectory=new StringBuilder("run,tick,x,y,z,vx,vy,vz\n");
        try(var w=c.worldBuilder().create()){
            save=w.getWorldSave();w.getServer().runCommand("time set day");w.getServer().runCommand("weather clear");w.getServer().runCommand("difficulty normal");base(w,.5,-60,-.5);c.waitTicks(4);
            int target=w.getServer().computeOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();p.setItemSlot(EquipmentSlot.MAINHAND,gear(s.overworld(),Items.DIAMOND_SWORD,"borrowed_flame",2));p.setRemainingFireTicks(240);var v=EntityType.HUSK.create(s.overworld(),EntitySpawnReason.TRIGGERED);v.setNoAi(true);v.setPos(.5,-60,1.6);s.overworld().addFreshEntity(v);return v.getId();});c.waitTicks(4);aim(c,.5,-59,1.6);c.getInput().pressKey(o->o.keyAttack);c.waitTicks(3);
            w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();check(!p.isOnFire()&&s.overworld().getEntity(target).isOnFire(),"real client melee transfers fire and extinguishes self");});shot(c,"01-borrowed-flame");
            base(w,10.5,-60,.5);w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();var bow=gear(s.overworld(),Items.CROSSBOW,"returning_feather",3);vanilla(s.overworld(),bow,"quick_charge",3);vanilla(s.overworld(),bow,"multishot",1);p.setItemSlot(EquipmentSlot.MAINHAND,bow);p.setItemSlot(EquipmentSlot.OFFHAND,new ItemStack(Items.ARROW));});c.waitTicks(3);c.getInput().lookAt(0,0);c.getInput().holdKey(o->o.keyUse);c.waitTicks(14);c.getInput().releaseKey(o->o.keyUse);c.waitTick();
            w.getServer().runOnServer(s->check(CrossbowItem.isCharged(s.getPlayerList().getPlayers().getFirst().getMainHandItem()),"real client quick-charge/multishot load"));shot(c,"02-returning-feather-loaded");c.getInput().pressKey(o->o.keyUse);c.waitTicks(2);w.getServer().runOnServer(s->check(!CrossbowItem.isCharged(s.getPlayerList().getPlayers().getFirst().getMainHandItem()),"stored crossbow shot clears once"));shot(c,"03-crossbow-fired");
            base(w,20.5,-60,.5);w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();var bow=gear(s.overworld(),Items.BOW,"swift_draw",3);vanilla(s.overworld(),bow,"power",3);vanilla(s.overworld(),bow,"infinity",1);p.setItemSlot(EquipmentSlot.MAINHAND,bow);p.setItemSlot(EquipmentSlot.OFFHAND,new ItemStack(Items.ARROW));});c.waitTicks(3);c.getInput().lookAt(0,-8);c.getInput().holdKey(o->o.keyUse);c.waitTicks(15);shot(c,"04-swift-draw-full");c.waitTicks(10);w.getServer().runOnServer(s->check(s.getPlayerList().getPlayers().getFirst().isUsingItem(),"full draw holds aim and never auto fires"));c.getInput().releaseKey(o->o.keyUse);c.waitTicks(2);w.getServer().runOnServer(s->check(s.overworld().getEntitiesOfClass(AbstractArrow.class,new AABB(15,-62,-5,25,-52,20)).stream().anyMatch(AbstractArrow::isCritArrow),"real release produces critical full-power arrow"));shot(c,"05-swift-draw-shot");
            // Measured local-player physics; only the initial teleport/launch is a fixture.
            double[] distance=new double[2],drop=new double[2];for(int run=0;run<2;run++){int index=run;base(w,30.5,-35,.5);w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();if(index==1)p.setItemSlot(EquipmentSlot.FEET,gear(s.overworld(),Items.DIAMOND_BOOTS,"paper_kite",3));p.setDeltaMovement(.3,-.05,0);p.connection.send(new net.minecraft.network.protocol.game.ClientboundSetEntityMotionPacket(p));});c.waitTicks(3);c.getInput().lookAt(-90,50);c.getInput().holdKey(o->o.keyShift);var start=c.computeOnClient(client->client.player.position());
                for(int tick=0;tick<=12;tick+=4){if(tick>0)c.waitTicks(4);int t=tick;c.runOnClient(client->{var p=client.player;var v=p.getDeltaMovement();trajectory.append(index).append(',').append(t).append(',').append(p.getX()).append(',').append(p.getY()).append(',').append(p.getZ()).append(',').append(v.x).append(',').append(v.y).append(',').append(v.z).append('\n');});shot(c,"06-kite-"+(run==1?"frame-":"control-")+tick);}
                var end=c.computeOnClient(client->client.player.position());distance[run]=end.subtract(start).horizontalDistance();drop[run]=start.y-end.y;if(run==1){double oldZ=end.z;c.getInput().holdKey(o->o.keyRight);c.waitTicks(4);c.getInput().releaseKey(o->o.keyRight);c.runOnClient(client->{check(Math.abs(client.player.getZ()-oldZ)>.015,"actual in-air right input adjusts landing direction");var v=client.player.getDeltaMovement();trajectory.append("1,16,").append(client.player.getX()).append(',').append(client.player.getY()).append(',').append(client.player.getZ()).append(',').append(v.x).append(',').append(v.y).append(',').append(v.z).append('\n');});shot(c,"06b-kite-steering");}c.getInput().releaseKey(o->o.keyShift);}
            check(distance[1]<distance[0]*.9&&Math.abs(drop[0]-drop[1])<.5,"actual client kite reduces horizontal drift while preserving vertical fall: "+Arrays.toString(distance)+" drops "+Arrays.toString(drop));report.append("Paper Kite measured drift ").append(Arrays.toString(distance)).append("; drop ").append(Arrays.toString(drop)).append(".\n");
            // Local tagged container outline through an opaque wall, no global ore scan.
            base(w,50.5,-60,.5);w.getServer().runOnServer(s->{for(int x=49;x<=55;x++)for(int y=-60;y<=-57;y++)for(int z=-1;z<=1;z++)s.overworld().setBlockAndUpdate(new BlockPos(x,y,z),Blocks.WATER.defaultBlockState());for(int y=-60;y<=-57;y++)for(int z=-1;z<=1;z++)s.overworld().setBlockAndUpdate(new BlockPos(53,y,z),Blocks.STONE.defaultBlockState());s.overworld().setBlockAndUpdate(new BlockPos(54,-60,0),Blocks.CHEST.defaultBlockState());});c.waitTicks(5);aim(c,54.5,-59.5,.5);shot(c,"07-reflection-without-helmet");w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();p.setItemSlot(EquipmentSlot.HEAD,gear(s.overworld(),Items.DIAMOND_HELMET,"water_reflection",1));});c.waitFor(client->WaterReflectionClient.count()>0);shot(c,"08-reflection-hidden-container");
            w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();p.teleportTo(50.5,-54,.5);});c.waitFor(client->WaterReflectionClient.count()==0);
            // The arrow travels into the actual raised shield under normal server ticking.
            base(w,65.5,-60,.5);w.getServer().runOnServer(s->s.getPlayerList().getPlayers().getFirst().setItemSlot(EquipmentSlot.OFFHAND,gear(s.overworld(),Items.SHIELD,"parry",2)));c.waitTicks(4);c.getInput().lookAt(0,0);c.getInput().holdKey(o->o.keyUse);c.waitTicks(6);
            int arrowId=w.getServer().computeOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();var a=new Arrow(s.overworld(),p,new ItemStack(Items.ARROW),new ItemStack(Items.BOW));a.setOwner((Entity)null);a.setPos(p.getX(),p.getY()+.35,p.getZ()+1.5);a.setDeltaMovement(0,0,-.7);s.overworld().addFreshEntity(a);return a.getId();});c.waitTicks(4);w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();var a=(AbstractArrow)s.overworld().getEntity(arrowId);check(a!=null&&a.getOwner()==p&&a.getDeltaMovement().z>0&&a.getY()>p.getY()+.7,"actual approaching low arrow reflected and safely above ground");});shot(c,"09-parry-low-arrow");c.getInput().releaseKey(o->o.keyUse);
            base(w,75.5,-60,.5);w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();var spear=gear(s.overworld(),Items.TRIDENT,"undertow",2);vanilla(s.overworld(),spear,"loyalty",3);var trident=new ThrownTrident(s.overworld(),p,spear);trident.setPos(75.5,-57,4.5);trident.setDeltaMovement(0,-.8,0);s.overworld().addFreshEntity(trident);var targetStand=EntityType.ARMOR_STAND.create(s.overworld(),EntitySpawnReason.TRIGGERED);targetStand.setPos(77.5,-60,4.5);s.overworld().addFreshEntity(targetStand);});c.getInput().lookAt(0,12);c.waitTicks(6);check(w.getServer().computeOnServer(s->TideVortices.count()>0),"normal server callback maintains actual vortex");shot(c,"10-undertow-active");c.waitTicks(12);shot(c,"11-undertow-pull");c.waitTicks(25);w.getServer().runOnServer(s->check(s.getPlayerList().getPlayers().getFirst().getInventory().countItem(Items.TRIDENT)==1,"normal client/server loyalty recovery returns exactly one original trident"));
            // Quiet walking and positive sprint control on the same native sensor.
            base(w,100.5,-60,.5);w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();p.setItemSlot(EquipmentSlot.FEET,gear(s.overworld(),Items.DIAMOND_BOOTS,"hush_step",1));s.overworld().setBlockAndUpdate(new BlockPos(99,-60,3),Blocks.SCULK_SENSOR.defaultBlockState());s.overworld().setBlockAndUpdate(new BlockPos(99,-60,5),Blocks.SCULK_SHRIEKER.defaultBlockState());});c.waitTicks(45);c.getInput().lookAt(0,10);c.getInput().holdKey(o->o.keyUp);c.waitTicks(16);c.getInput().releaseKey(o->o.keyUp);w.getServer().runOnServer(s->check(s.overworld().getBlockState(new BlockPos(99,-60,3)).getValue(SculkSensorBlock.PHASE)==net.minecraft.world.level.block.state.properties.SculkSensorPhase.INACTIVE,"real quiet walking emits no STEP vibration to sensor"));aim(c,99.5,-59.7,3.5);shot(c,"12-hush-step-sensor-inactive");
            w.getServer().runOnServer(s->s.getPlayerList().getPlayers().getFirst().teleportTo(100.5,-60,.5));c.waitTicks(3);c.getInput().lookAt(0,0);c.getInput().holdKey(o->o.keySprint);c.getInput().holdKey(o->o.keyUp);c.waitTicks(10);c.getInput().releaseKey(o->o.keyUp);c.getInput().releaseKey(o->o.keySprint);aim(c,99.5,-59.7,3.5);shot(c,"13-sprint-vibration-control");
            w.getServer().runOnServer(server->check(server.overworld().getBlockState(new BlockPos(99,-60,3)).getValue(SculkSensorBlock.PHASE)==net.minecraft.world.level.block.state.properties.SculkSensorPhase.ACTIVE,"normal sprint still activates sensor"));
            tooltips(c,w,"en_us");tooltips(c,w,"zh_cn");
            // A real running ledge transition, not manually calling the bridge effect.
            base(w,124.5,-60,.5);w.getServer().runOnServer(s->{for(int x=126;x<=128;x++)for(int y=-64;y<=-61;y++)for(int z=-2;z<=2;z++)s.overworld().setBlockAndUpdate(new BlockPos(x,y,z),Blocks.AIR.defaultBlockState());var p=s.getPlayerList().getPlayers().getFirst();p.setItemSlot(EquipmentSlot.FEET,gear(s.overworld(),Items.DIAMOND_BOOTS,"star_bridge",1));});c.waitTicks(5);c.getInput().lookAt(-90,48);c.getInput().holdKey(o->o.keySprint);c.getInput().holdKey(o->o.keyUp);
            c.waitFor(client->!client.level.getEntitiesOfClass(StarStep.class,client.player.getBoundingBox().inflate(5)).isEmpty());shot(c,"14-star-bridge-edge");c.waitTicks(3);shot(c,"15-star-bridge-walking");c.waitFor(client->client.player.getX()>129.3);shot(c,"15b-star-bridge-far-ledge");c.getInput().releaseKey(o->o.keyUp);c.getInput().releaseKey(o->o.keySprint);aim(c,127.5,-60.1,.5);shot(c,"15c-star-bridge-crossed-lookback");
            w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();check(p.getX()>129.3&&p.getY()>-60.5&&!StarBridgeData.get(s).ready(p.getUUID(),s.overworld().getGameTime()),"real server collision kept runner near ledge height and spent cooldown");});
            dataJson=w.getServer().computeOnServer(s->ResearchWorldData.get(s).exportJson());report.append("Real client: melee fire transfer; quick-charge/multishot crossbow loaded and fired; Swift Draw full charge held without auto-fire and released critical arrow; underwater tagged outline clears at surface; low incoming arrow parried; normal server vortex; quiet walking native sensor and sprint control; native runner creates collidable bridge.\n");
        }
        try(var w=save.open()){c.waitTicks(6);w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();check(BatchEffects.level(p,p.getItemBySlot(EquipmentSlot.FEET),"star_bridge")==1,"new enchantment persists on equipment");check(!StarBridgeData.get(s).ready(p.getUUID(),s.overworld().getGameTime()),"bridge cooldown persists across real disk restart");check(s.overworld().getEntitiesOfClass(StarStep.class,p.getBoundingBox().inflate(32)).isEmpty(),"no temporary collision entities survive save/unload");check(com.google.gson.JsonParser.parseString(dataJson).equals(com.google.gson.JsonParser.parseString(ResearchWorldData.get(s).exportJson())),"expanded research snapshot unchanged across restart");});shot(c,"16-reloaded-no-ghost-bridge");report.append("Disk restart: expanded research snapshot and equipped enchantment persist; star cooldown stays spent; temporary noSave footholds absent.\n");}
        try{var dir=Path.of("../reports/lost-batch-two");Files.createDirectories(dir);Files.writeString(dir.resolve("client.txt"),report.toString());Files.writeString(dir.resolve("kite-trajectory.csv"),trajectory.toString());}catch(Exception e){throw new RuntimeException(e);}
    }
}
